import{_ as a,o,c as t,a3 as s}from"./chunks/framework.CchDE9cb.js";const i="/capacitylens/assets/timeoff-draw.Ed_W2ZCB.jpg",m=JSON.parse('{"title":"Time off","description":"Record holiday, sick leave and unpaid leave so the schedule always shows real availability, not just booked work.","frontmatter":{"title":"Time off","description":"Record holiday, sick leave and unpaid leave so the schedule always shows real availability, not just booked work."},"headers":[],"relativePath":"guide/time-off.md","filePath":"guide/time-off.md","lastUpdated":null}'),r={name:"guide/time-off.md"};function n(l,e,h,d,c,f){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="time-off" tabindex="-1">Time off <a class="header-anchor" href="#time-off" aria-label="Permalink to &quot;Time off&quot;">​</a></h1><p><a href="/capacitylens/reference/glossary">Time off</a> is a block on the schedule marking a <a href="/capacitylens/reference/glossary">person</a> unavailable, drawn on the same canvas as their work so capacity never has to be checked against a separate calendar. This page covers recording it and how it interacts with allocations.</p><h2 id="record-time-off" tabindex="-1">Record time off <a class="header-anchor" href="#record-time-off" aria-label="Permalink to &quot;Record time off&quot;">​</a></h2><ol><li>Open <strong>Time off</strong> and click <strong>Add time off</strong> — or, on the schedule, switch the toolbar&#39;s draw mode from &quot;Work&quot; to &quot;Time off&quot; and drag across the days on a person&#39;s row.</li><li>Choose the person, the start and end dates, and a type: holiday, sick, unpaid, or other.</li><li>Add a note if you need to — for example, which half of the day, or a return date. Notes are only visible to Admins and Owners; other roles see that time off exists without the detail. See <a href="/capacitylens/getting-started/roles-and-permissions">Roles and permissions</a>.</li></ol><p><img src="'+i+'" alt="The schedule with draw mode switched to Time off: work allocations dim and a holiday block is highlighted"></p><h2 id="how-it-shows-on-the-schedule" tabindex="-1">How it shows on the schedule <a class="header-anchor" href="#how-it-shows-on-the-schedule" aria-label="Permalink to &quot;How it shows on the schedule&quot;">​</a></h2><p>Time off renders as a hatched block on the person&#39;s row — no project colour, so it&#39;s never mistaken for booked work. It sits in the same lane as allocation bars, which means a quick glance at a row tells you whether someone is busy, off, or free.</p><p><a href="/capacitylens/reference/glossary">External parties</a> — outside companies like print shops or overflow studios you hand work to but don&#39;t manage — can&#39;t have time off recorded against them, since they carry no hours and no capacity on the schedule. See <a href="/capacitylens/guide/people-and-placeholders">People and placeholders</a> for the difference between an external party, a placeholder and a person.</p><h2 id="time-off-and-allocations" tabindex="-1">Time off and allocations <a class="header-anchor" href="#time-off-and-allocations" aria-label="Permalink to &quot;Time off and allocations&quot;">​</a></h2><p>Recording time off doesn&#39;t automatically remove or block overlapping allocations. Instead, if you try to book someone on days they&#39;re already off, the allocation form warns you that the booking overlaps their time off — so you can see the conflict and decide, rather than have CapacityLens silently prevent it or silently ignore it.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p>Back to <a href="/capacitylens/guide/the-schedule">The schedule</a> to see how time off and allocations read together on the grid, or <a href="/capacitylens/guide/settings">Settings</a> to see the company-wide switches that affect what&#39;s visible.</p>',12)])])}const u=a(r,[["render",n]]);export{m as __pageData,u as default};
